from .collectable import CollectableGroup
from .async_collectable import AsyncCollectableGroup
from taf.internal.managedobject import ManagedGroup
from .startable import StartableGroup


class CollectorGroup(ManagedGroup, CollectableGroup):
    """
    Group, where the members are collectors or groups of them.
    """


class StartableCollectorGroup(StartableGroup, CollectorGroup):
    """
    Group, where the members are startable collectors or groups of them.
    """


class AsyncCollectorGroup(ManagedGroup, AsyncCollectableGroup):
    """
    Group, where the members are async collectors or groups of them.
    """
